# Test case 1: Simple portfolio with two stocks; allocations sum to 1.
def fake_volatility(prices):
    # Let's suppose volatility is simply max-min of prices
    return max(prices) - min(prices)

def portfolio_risk_assessment_func(portfolio, volatility_fn):
    total = 0.0
    for stock, data in portfolio.items():
        vol = volatility_fn(data['prices'])
        total += vol * data['allocation']
    return total

