# Assuming calculate_stock_volatility(prices) returns the standard deviation of price changes
# Example: prices = [100, 105, 95, 100] volatility = stddev([105-100, 95-105, 100-95])

def dummy_volatility(prices):
    # Simple stddev of price changes for illustration (not actual implementation)
    if len(prices) < 2:
        return 0.0
    changes = [prices[i+1] - prices[i] for i in range(len(prices)-1)]
    mean = sum(changes) / len(changes)
    var = sum((x-mean)**2 for x in changes) / len(changes)
    return var**0.5

