# Example stub for testing purposes:
def calculate_stock_volatility(prices):
    # Use sample std dev for test purposes (use correct formula in production)
    if not prices or len(prices) < 2:
        return 0.0
    avg = sum(prices) / len(prices)
    variance = sum((x - avg) ** 2 for x in prices) / (len(prices) - 1)
    return variance ** 0.5

def portfolio_risk_assessment(portfolio):
    '''
    Takes a dict where keys are stock names and values have 'prices' list and 'allocation' float.
    For each stock, calls calculate_stock_volatility(prices), multiplies by allocation, sums all weighted volatilities.
    Returns: float representing total portfolio risk as weighted sum.
    '''
    total_risk = 0.0
    for stock in portfolio:
        prices = portfolio[stock]['prices']
        allocation = portfolio[stock]['allocation']
        volatility = calculate_stock_volatility(prices)
        total_risk += volatility * allocation
    return total_risk

