def aggregate_temperature(sensor_strings):
    '''
    Takes a list of raw sensor strings. Use parse_sensor_reading to parse each one.
    Collect all temperature values that are not None. Return average of all temperatures rounded to 2 decimals.
    Return 0.0 if no valid temperatures.
    '''
    temperatures = []
    for sensor_string in sensor_strings:
        reading = parse_sensor_reading(sensor_string)
        temp = reading.get('temperature')
        if temp is not None:
            temperatures.append(temp)
    if not temperatures:
        return 0.0
    avg_temp = sum(temperatures) / len(temperatures)
    return round(avg_temp, 2)
